  let toolStart=false,toolChanging=false,toolSearch='',reviewerChanging=false,toolSession=0,renderedToolSession=-1,toolAdvancedOpen=false;
  let procedureStart=false,procedureChoice='',procedureNames={},procedureDescriptions={},procedureScopes={},procedureSession=0,reportedStartContext='null';
  let resources={skills:[],available:false},resourcesLoaded=false,resourcesLoading=false,resourcesError='';
