  function assigneeHTML(node){const selected=node.assignee?node.assignee.kind+':'+node.assignee.id:'',choices={'':'담당자 미지정',...optionList(people())};if(selected&&!choices[selected])choices[selected]='기존 담당자 · 현재 접근 확인 필요';return select('assignee','작업 담당자 · Native 사용자/그룹',selected,choices);}
  function openTool(value){toolSession++;toolAdvancedOpen=false;toolDraft=value?clone(value):null;toolId=toolDraft?.id || '';toolDirty=false;toolSchemaText=toolDraft?.output_schema?JSON.stringify(toolDraft.output_schema,null,2):'';toolSchemaError='';toolStart=false;toolChanging=false;reviewerChanging=false;}
