  function stashTool(){captureToolAdvanced();if(actor)toolDrafts.set(toolKey(),{draft:toolDraft?clone(toolDraft):null,toolDirty,toolSchemaText,toolSchemaError,toolStart,toolChanging,toolSearch,reviewerChanging,toolAdvancedOpen});}
  function restoreTool(){const cached=toolDrafts.get(toolKey());openTool(cached?.draft || null);if(cached){toolDirty=cached.toolDirty;toolSchemaText=cached.toolSchemaText;toolSchemaError=cached.toolSchemaError;toolStart=cached.toolStart;toolChanging=cached.toolChanging;toolSearch=cached.toolSearch;reviewerChanging=cached.reviewerChanging;toolAdvancedOpen=Boolean(cached.toolAdvancedOpen);}}
