  function applyCreatedDescription(){const id=editor?.id||record?.id;if(!id||workflowId()!==id)return;const descriptionKey=JSON.stringify([actor,selection.system_id||'',id]);if(!pendingProcedureDescriptions.has(descriptionKey))return;const description=pendingProcedureDescriptions.get(descriptionKey);pendingProcedureDescriptions.delete(descriptionKey);if(editor.description!==description){editor.description=description;dirty=true;stash();}}
