  function startInputsHTML(root){const inputs=(root?.inputs||[]).filter(input=>(input.scope||'run')==='run');return `<div class="ew-author-heading"><h3>시작할 때 받는 값</h3><small>${inputs.length}개</small></div><p class="ew-schedule-note">이번 진행 건을 시작할 때 물어볼 항목을 정합니다.</p>${inputs.map((input,index)=>{const attrs=`data-start-input-id="${esc(input.id)}"`,control=(key,label,value,type='input',extra='')=>(type==='textarea'?area(key,label,value,`${attrs} data-definition-field="${key}" ${extra}`):textInput(key,label,value,`${attrs} data-definition-field="${key}" ${extra}`));return `<section class="ew-start-input-definition"><div class="ew-author-heading"><h4>입력 ${index+1}</h4>${b('삭제','start_input_delete',`data-id="${esc(input.id)}" class="ew-author-link" aria-label="${esc(input.name||'입력 '+(index+1))} 삭제"`)}</div><div class="ew-author-fields">${control('name','값 이름',input.name||'','input','maxlength="160"')}${select('input_type','형식',input.type,workAuthoring.inputTypes,`${attrs} data-definition-field="type"`)}${control('description','설명 · 선택',input.description||'','textarea')}${input.type==='number'?control('unit','단위 · 선택',input.unit||''):''}${['single','multi'].includes(input.type)?(!input.options_source||input.options_source==='manual'?control('options','선택지 · 한 줄에 하나',(input.options||[]).map(option=>typeof option==='string'?option:option.name||option.id).join('\n'),'textarea'):`<p class="ew-author-muted">기존 선택지 연결을 유지합니다. ${b('설정 확인','start_input_edit',`data-id="${esc(input.id)}" class="ew-author-link"`)}</p>`):''}<div class="ew-author-inline"><small>저장 범위 · 이번 진행 건</small><label><input type="checkbox" ${attrs} data-definition-field="required" ${input.required?'checked':''}>필수 값</label></div></div></section>`;}).join('')||'<p class="ew-author-empty">정한 항목이 없습니다. 시작할 때 필요한 값이 있다면 추가해 주세요.</p>'}${b('＋ 시작 입력 추가','start_input_add','class="ew-author-link" data-mutation')}<p class="ew-schedule-note">여기서는 질문의 이름과 형식을 정합니다. 실제 답은 업무를 시작하는 사람이 입력합니다.</p>`;}
  function definitionFieldEvent(event){const target=event.target,key=target.dataset?.definitionField,inputId=target.dataset?.startInputId,judgmentId=target.dataset?.judgmentJobId;if(!key||inputId===undefined&&judgmentId===undefined)return false;if(!canAuthor())return true;if(!['input','change'].includes(event.type))return false;let object,judgmentNode,judgmentIndex;
    if(inputId!==undefined)object=nodes(editor).find(node=>node.type==='p')?.inputs?.find(input=>input.id===inputId);else{const node=jobs(editor).find(item=>item.id===judgmentId),index=Number(target.dataset.judgmentIndex);if(!node||!nodeJudgments(node)?.[index])return true;judgmentNode=node;judgmentIndex=index;object=nodeJudgments(node)[index];}
    if(!object)return true;const before=JSON.stringify(object);let value=target.type==='checkbox'?target.checked:target.value;if(key==='options'){const current=(object.options||[]).map(option=>typeof option==='string'?option:option.name||option.id).join('\n');if(value===current)return true;value=String(value).split('\n').map(item=>item.trim()).filter(Boolean);}if(!['name','type','description','unit','options','required','label','status','consequence'].includes(key))return true;if(JSON.stringify(object[key]??(target.type==='checkbox'?false:''))===JSON.stringify(value))return true;if(judgmentNode){if(!judgmentNode.judgments)judgmentNode.judgments=clone(nodeJudgments(judgmentNode));object=judgmentNode.judgments[judgmentIndex];}object[key]=value;if(JSON.stringify(object)!==before){dirty=true;stash();const status=host?.querySelector?.('[data-author-status]');if(status){status.textContent='변경 있음 · 저장 안 됨';status.dataset.dirty='true';}setBusy(busy);if(key==='type'){focusRequest={field:'[data-start-input-id="'+inputId+'"][data-definition-field="type"]'};paint();}}return true;
  }
