      <section class="ew-schedule-section"><div class="ew-author-heading"><h3>단계 기한</h3><small>회차 기준일 기준 · D±일</small></div>${stages.map((stage,index)=>{const deadline=s.stage_deadlines?.[stage.id] || {};return `<div class="ew-schedule-stage-deadline"><h4>${index+1}. ${esc(stage.name)}</h4><div class="ew-schedule-offset-fields">${textInput('stage_start:'+stage.id,'시작 일수',deadline.offset_days??'','type="number" min="-366" max="366" placeholder="예: -2"')}${textInput('stage_end:'+stage.id,'종료 일수 · 선택',deadline.end_offset_days??'','type="number" min="-366" max="366" placeholder="예: 0"')}</div></div>`;}).join('') || '<p class="ew-schedule-note">업무 내용에서 단계를 추가한 뒤 기한을 정하세요.</p>'}<p class="ew-schedule-note">0은 기준일, 음수는 기준일 전, 양수는 기준일 후입니다.</p></section>
